local WigMaker = {}
local PRODUCTS = {
    horsehair_wig = { name = "Konjskodlana lasulja", hairCost = 2, linenCost = 1, time = 3, cost = 30, prestige = 2, description = "Konjskodlana lasulja za uradnike." },
    human_hair_wig = { name = "Človeškodlana lasulja", humanHairCost = 2, silkCost = 1, time = 5, cost = 80, prestige = 5, happiness = 1, description = "Človeškodlana lasulja za plemiče." },
    powdered_wig = { name = "Prašna lasulja", humanHairCost = 2, silkCost = 1, starchCost = 1, time = 7, cost = 180, prestige = 9, happiness = 2, description = "Prašna lasulja za dvorno modo." },
    silver_thread_wig = { name = "Srebrno nitna lasulja", humanHairCost = 2, silverCost = 1, silkCost = 1, starchCost = 1, time = 10, cost = 420, prestige = 15, happiness = 3, description = "Lasulja s srebrnimi nitmi za visoke plemiče." },
    gold_thread_wig = { name = "Zlatorobna lasulja", humanHairCost = 3, goldCost = 1, silverCost = 1, silkCost = 1, jewelCost = 1, time = 13, cost = 900, prestige = 25, happiness = 5, description = "Zlatorobna lasulja z draguljem za kraljeve svetovalce." },
    royal_grand_wig = { name = "Kraljevski veliki lasulja", humanHairCost = 4, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, silkCost = 2, time = 18, cost = 2200, prestige = 50, happiness = 11, description = "Velika kraljevska lasulja z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Lasuljarska delavnica", cost = { gold = 280, wood = 120, stone = 200 }, upkeep = 7, qualityBonus = 5 },
    wig_room = { name = "Lasuljnica", cost = { gold = 900, wood = 250, stone = 400, hair = 10 }, upkeep = 22, qualityBonus = 18 },
    styling_room = { name = "Oblikovalnica", cost = { gold = 2200, wood = 350, stone = 600, silver = 25, silk = 8 }, upkeep = 55, qualityBonus = 30 },
    royal_wig_atelier = { name = "Kraljevski atelje lasulj", cost = { gold = 9000, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
WigMaker.hairStock = 18; WigMaker.humanHairStock = 12; WigMaker.linenStock = 10; WigMaker.silkStock = 8; WigMaker.starchStock = 10; WigMaker.silverStock = 8; WigMaker.goldStock = 6; WigMaker.jewelStock = 6; WigMaker.pearlStock = 4
WigMaker.productStock = {}; WigMaker.buildings = {}; WigMaker.maker = nil; WigMaker.activeMaking = {}; WigMaker.totalProducts = 0; WigMaker.dayTimer = 0
function WigMaker.init() WigMaker.hairStock=18; WigMaker.humanHairStock=12; WigMaker.linenStock=10; WigMaker.silkStock=8; WigMaker.starchStock=10; WigMaker.silverStock=8; WigMaker.goldStock=6; WigMaker.jewelStock=6; WigMaker.pearlStock=4; WigMaker.productStock={}; WigMaker.buildings={}; WigMaker.maker=nil; WigMaker.activeMaking={}; WigMaker.totalProducts=0; WigMaker.dayTimer=0; print("[WigMaker] Royal Wig Maker System initialized (6 products, 4 buildings)") end
function WigMaker.hireMaker(n,s) s=s or math.random(50,90); local c=520+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WigMaker.maker={name=n or ("Lasuljar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lasuljar najet: %s (spretnost: %d)",WigMaker.maker.name,s),"success") end; return true end
function WigMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WigMaker.build(id) local ok,e=WigMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WigMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WigMaker.getQualityBonus() local b=0; for _,bd in ipairs(WigMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WigMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.hairCost and WigMaker.hairStock<(d.hairCost or 0) then return false,"Premalo konjskih dlak" end; if d.humanHairCost and WigMaker.humanHairStock<(d.humanHairCost or 0) then return false,"Premalo človeških dlak" end; if d.linenCost and WigMaker.linenStock<(d.linenCost or 0) then return false,"Premalo lana" end; if d.silkCost and WigMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.starchCost and WigMaker.starchStock<(d.starchCost or 0) then return false,"Premalo škroba" end; if d.silverCost and WigMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WigMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WigMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WigMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WigMaker.buildings==0 then return false,"Potrebna delavnica" end; if not WigMaker.maker then return false,"Potreben lasuljar" end; return true end
function WigMaker.make(pt,qty) qty=qty or 1; local ok,e=WigMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.hairCost then WigMaker.hairStock=WigMaker.hairStock-d.hairCost*qty end; if d.humanHairCost then WigMaker.humanHairStock=WigMaker.humanHairStock-d.humanHairCost*qty end; if d.linenCost then WigMaker.linenStock=WigMaker.linenStock-d.linenCost*qty end; if d.silkCost then WigMaker.silkStock=WigMaker.silkStock-d.silkCost*qty end; if d.starchCost then WigMaker.starchStock=WigMaker.starchStock-d.starchCost*qty end; if d.silverCost then WigMaker.silverStock=WigMaker.silverStock-d.silverCost*qty end; if d.goldCost then WigMaker.goldStock=WigMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WigMaker.jewelStock=WigMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WigMaker.pearlStock=WigMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WigMaker.maker then t=math.max(1,t-math.floor(WigMaker.maker.skill/12)) end; table.insert(WigMaker.activeMaking,{id="wig_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WigMaker.completeMaking(m) local q=1.0+(WigMaker.getQualityBonus()/100); if WigMaker.maker then q=q+(WigMaker.maker.skill/180) end; q=math.min(2.0,q); WigMaker.productStock[m.productType]=(WigMaker.productStock[m.productType] or 0)+m.quantity; WigMaker.totalProducts=WigMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WigMaker.maker then WigMaker.maker.itemsMade=WigMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then WigMaker.maker.skill=math.min(100,WigMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lasulja izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"wig.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function WigMaker.update(dt) if not _G.state then return end; WigMaker.dayTimer=WigMaker.dayTimer+dt; if WigMaker.dayTimer>=30 then WigMaker.dayTimer=0; for i=#WigMaker.activeMaking,1,-1 do local m=WigMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WigMaker.completeMaking(m); table.remove(WigMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WigMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WigMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WigMaker.getStats() return {hairStock=WigMaker.hairStock,humanHairStock=WigMaker.humanHairStock,linenStock=WigMaker.linenStock,silkStock=WigMaker.silkStock,starchStock=WigMaker.starchStock,silverStock=WigMaker.silverStock,goldStock=WigMaker.goldStock,jewelStock=WigMaker.jewelStock,pearlStock=WigMaker.pearlStock,productStock=WigMaker.productStock,numBuildings=#WigMaker.buildings,hasMaker=WigMaker.maker~=nil,makerName=WigMaker.maker and WigMaker.maker.name or "—",makerSkill=WigMaker.maker and WigMaker.maker.skill or 0,activeMaking=#WigMaker.activeMaking,totalProducts=WigMaker.totalProducts} end
return WigMaker
